DO $$DECLARE definition text;BEGIN SELECT pg_get_functiondef('public.signal_note_report(jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'e.kind=''assign''','e.kind IN (''assign'',''reopen'',''cancel'')'); definition:=replace(definition,'e.detail->>''to'' sale','CASE WHEN e.kind=''assign'' THEN e.detail->>''to'' WHEN e.kind=''reopen'' THEN s.assigned_to::text ELSE NULL END sale'); definition:=replace(definition,'a.ends IS NULL OR n.created_at<a.ends','n.created_at<least(coalesce(a.ends,''infinity''::timestamptz),coalesce((SELECT min(z.created_at) FROM public.opportunity_signal_notes z WHERE z.signal_id=a.signal_id AND z.status_to IN (''won'',''lost'') AND z.status_from IS DISTINCT FROM z.status_to AND z.created_at>=a.starts),''infinity''::timestamptz))'); definition:=replace(definition,'c.ends IS NULL OR n.created_at<c.ends','n.created_at<least(coalesce(c.ends,''infinity''::timestamptz),coalesce((SELECT min(z.created_at) FROM public.opportunity_signal_notes z WHERE z.signal_id=c.signal_id AND z.status_to IN (''won'',''lost'') AND z.status_from IS DISTINCT FROM z.status_to AND z.created_at>=c.starts),''infinity''::timestamptz))');EXECUTE definition;END$$;